pub fn generated_interface(name: &str) -> Option<&'static GeneratedInterface> {
    GENERATED_INTERFACES.iter().find(|interface| interface.name == name)
}
pub fn generated_member(
    interface: &str,
    member: &str,
) -> Option<&'static GeneratedMember> {
    generated_interface(interface)?
        .members
        .iter()
        .find(|candidate| candidate.name == member)
}
#[allow(dead_code)]
pub fn generated_member_by_id(
    id: GeneratedMemberId,
) -> Option<(&'static GeneratedInterface, &'static GeneratedMember)> {
    let interface = GENERATED_INTERFACES.get((id.0 >> 16) as usize)?;
    let member = interface.members.get((id.0 & 0xffff) as usize)?;
    (member.id == id).then_some((interface, member))
}
